<script setup lang="ts">import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';import{fromProjection}from'../../domain/price-snapshot';import{validateOrderSnapshot}from'../../domain/snapshot-flow';import type{OrderProjection}from'../../domain/types';const p=ref<OrderProjection|null>(null),orderRef=ref(''),error=ref('');const ready=computed(()=>validateOrderSnapshot(uni,orderRef.value,p.value?fromProjection(p.value):null));async function refresh(){if(!orderRef.value)return;try{p.value=await api.getProjection(orderRef.value)}catch{error.value='读取失败。'}}onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()})</script>
<template><view class="page"><AppHeader left="← 订单" @left="uni.navigateBack()"/><view class="content"><view class="heading" role="heading" aria-level="1">订单最新状态</view><StatusNotice v-if="error" tone="risk" title="读取错误">{{error}}</StatusNotice><StatusNotice v-if="p&&!ready" tone="risk" title="STALE / 冻结快照不一致">后续业务动作资格为 0。</StatusNotice><view class="card"><view class="kv"><text>号码/运营商/商品</text><text>{{p?.maskedPhone}} / {{p?.operatorName}} / {{p?.productName}}</text></view><view class="kv"><text>总价</text><text>{{p?.total?.currency}} {{p?.total?.minor}}</text></view><view class="kv"><text>快照</text><text>{{p?.priceSnapshotRef}} / {{p?.priceVersion}} / {{p?.priceValidUntil}}</text></view></view></view><view class="action"><button class="primary" @click="refresh">只读查询</button></view></view></template><style src="../../styles/shared.css"></style>
